/* @file tb_uart.sv
 * 
 * Full disclosure: this file was generated by ChatGPT to test whether UART_RX
 * was able to receive messages correctly (meaning SOF occured on time, etc.).  
 * 
 * @author ChatGPT
 */

`default_nettype none
`timescale 1ns/1ps

module tb_uart;
  localparam integer CLOCK_FREQ = 50_000_000;
  localparam integer BAUD_RATE = 115_200;
  localparam integer CLOCKS_PER_BIT = CLOCK_FREQ / BAUD_RATE;

  logic clock = 1'b0;
  logic reset_n = 1'b0;
  logic serial_rx = 1'b1;
  logic serial_tx;
  logic [7:0] rx_data;
  logic rx_data_valid;
  logic start_bit_detected;
  logic framing_error;
  logic rx_overflow;
  logic tx_busy;
  logic monochrome;
  logic [7:0] transmitted_data;
  logic [6:0] decoded_segments;
  integer sof_count = 0;
  integer valid_count = 0;

  always #10 clock = ~clock;

  UART #(
    .CLOCK_FREQ(CLOCK_FREQ),
    .BAUD_RATE(BAUD_RATE)
  ) dut (
    .clock,
    .reset_n,
    .serial_rx,
    .serial_tx,
    .rx_data,
    .rx_data_valid,
    .start_bit_detected,
    .framing_error,
    .rx_overflow,
    .tx_busy,
    .monochrome
  );

  SevenSegmentHex decoder (
    .value({3'b0, monochrome}),
    .segments(decoded_segments)
  );

  always @(posedge clock) begin
    if (start_bit_detected)
      sof_count <= sof_count + 1;
    if (rx_data_valid)
      valid_count <= valid_count + 1;
  end

  task automatic drive_uart_byte(input logic [7:0] value);
    integer bit_number;
    begin
      serial_rx = 1'b0;
      repeat (CLOCKS_PER_BIT) @(posedge clock);
      for (bit_number = 0; bit_number < 8; bit_number = bit_number + 1) begin
        serial_rx = value[bit_number];
        repeat (CLOCKS_PER_BIT) @(posedge clock);
      end
      serial_rx = 1'b1;
      repeat (CLOCKS_PER_BIT) @(posedge clock);
    end
  endtask

  task automatic receive_uart_byte(output logic [7:0] value);
    integer bit_number;
    begin
      @(negedge serial_tx);
      repeat (CLOCKS_PER_BIT / 2) @(posedge clock);
      if (serial_tx !== 1'b0)
        $fatal(1, "TX start bit was not low at its midpoint");
      for (bit_number = 0; bit_number < 8; bit_number = bit_number + 1) begin
        repeat (CLOCKS_PER_BIT) @(posedge clock);
        value[bit_number] = serial_tx;
      end
      repeat (CLOCKS_PER_BIT) @(posedge clock);
      if (serial_tx !== 1'b1)
        $fatal(1, "TX stop bit was not high at its midpoint");
    end
  endtask

  initial begin
    repeat (5) @(posedge clock);
    reset_n = 1'b1;
    repeat (5) @(posedge clock);

    // A dark RGB triplet has an average below 128 and produces 8'h00.
    fork
      begin
        drive_uart_byte(8'h08);
        drive_uart_byte(8'h08);
        drive_uart_byte(8'h08);
      end
      receive_uart_byte(transmitted_data);
    join

    repeat (20) @(posedge clock);

    if (sof_count != 3)
      $fatal(1, "Expected three qualified SOF pulses, observed %0d", sof_count);
    if (valid_count != 3)
      $fatal(1, "Expected three received bytes, observed %0d", valid_count);
    if (rx_data !== 8'h08)
      $fatal(1, "Expected RX data 08, observed %02h", rx_data);
    if (transmitted_data !== 8'h00 || monochrome !== 1'b0)
      $fatal(1, "Dark RGB triplet did not produce monochrome zero");
    if (decoded_segments !== 7'b1000000)
      $fatal(1, "HEX2 did not decode monochrome zero: %07b", decoded_segments);
    if (framing_error || rx_overflow)
      $fatal(1, "Unexpected UART error indication");

    // A bright RGB triplet has an average above 128 and produces 8'h01.
    fork
      begin
        drive_uart_byte(8'hff);
        drive_uart_byte(8'hff);
        drive_uart_byte(8'hff);
      end
      receive_uart_byte(transmitted_data);
    join

    repeat (20) @(posedge clock);

    if (sof_count != 6 || valid_count != 6)
      $fatal(1, "The second RGB triplet was not fully received");
    if (transmitted_data !== 8'h01 || monochrome !== 1'b1)
      $fatal(1, "Bright RGB triplet did not produce monochrome one");
    if (decoded_segments !== 7'b1111001)
      $fatal(1, "HEX2 did not decode monochrome one: %07b", decoded_segments);
    if (framing_error || rx_overflow)
      $fatal(1, "Unexpected UART error indication");

    $display("PASS: dark and bright RGB triplets converted and transmitted");
    $finish;
  end

  initial begin
    #1ms;
    $fatal(1, "Simulation timeout");
  end
endmodule : tb_uart
